"""The historical fixture must be generated by the actual accepted release."""

from __future__ import annotations

import hashlib
import json
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "fixtures" / "v070"


class HistoricalFixture(unittest.TestCase):
    def manifest(self) -> dict:
        return json.loads((ROOT / "manifest.json").read_text())

    def test_original_revision_and_three_workspaces(self) -> None:
        value = self.manifest()
        self.assertTrue(value["source_commit"].startswith("1359118"))
        self.assertEqual(value["version"], "0.7.0")
        self.assertEqual(set(value["tenants"]), {"hq", "dept-01", "sub-01"})
        self.assertEqual(value["unprovisioned_tenant"], "dept-02")

    def test_artifact_hashes(self) -> None:
        for name, expected in self.manifest()["files"].items():
            self.assertEqual(hashlib.sha256((ROOT / name).read_bytes()).hexdigest(), expected, name)

    def test_roles_and_detail_routes(self) -> None:
        value = self.manifest()
        self.assertEqual({a["role"] for a in value["accounts"]}, {"admin", "modeler", "reviewer"})
        self.assertTrue(any(a.get("must_change_password") for a in value["accounts"]))
        self.assertTrue(
            {"material", "project", "task", "asset", "authority", "collection", "dataset", "source", "skill"}
            <= value["details"].keys()
        )

    def test_original_column_contract(self) -> None:
        for tenant in self.manifest()["tenants"]:
            value = json.loads((ROOT / (tenant + ".json")).read_text())
            self.assertEqual(len(value["columns"]["entities"]), 12)
            self.assertEqual(len(value["columns"]["relations"]), 7)
            self.assertNotIn("schema_migrations", value["tables"])
